import{_ as s,c as n,o as t,a5 as e}from"./chunks/framework.DorIfSpC.js";const h=JSON.parse('{"title":"從零理解神經網路（二）：為什麼激活函數如此重要？","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/learning/micrograd_visualize/02-activation-functions"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/learning/micrograd_visualize/02-activation-functions"}],["meta",{"property":"og:title","content":"從零理解神經網路（二）：為什麼激活函數如此重要？ | 星智未來"}],["meta",{"name":"twitter:title","content":"從零理解神經網路（二）：為什麼激活函數如此重要？ | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"從零理解神經網路（二）：為什麼激活函數如此重要？\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/learning/micrograd_visualize/02-activation-functions\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/learning/micrograd_visualize/02-activation-functions\\"}}"]]},"headers":[],"relativePath":"learning/micrograd_visualize/02-activation-functions.md","filePath":"learning/micrograd_visualize/02-activation-functions.md","lastUpdated":1768108012000}'),p={name:"learning/micrograd_visualize/02-activation-functions.md"};function l(i,a,r,o,d,c){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="從零理解神經網路-二-為什麼激活函數如此重要" tabindex="-1">從零理解神經網路（二）：為什麼激活函數如此重要？ <a class="header-anchor" href="#從零理解神經網路-二-為什麼激活函數如此重要" aria-label="Permalink to &quot;從零理解神經網路（二）：為什麼激活函數如此重要？&quot;">​</a></h1><blockquote><p>本文是「從零理解神經網路」系列的第二篇。上一篇我們認識了神經元，這篇要回答一個關鍵問題：為什麼神經網路需要「激活函數」？</p></blockquote><h2 id="一個令人驚訝的事實" tabindex="-1">一個令人驚訝的事實 <a class="header-anchor" href="#一個令人驚訝的事實" aria-label="Permalink to &quot;一個令人驚訝的事實&quot;">​</a></h2><p>先說結論：<strong>如果沒有激活函數，不管你的神經網路有多少層，它都等價於一個單層網路。</strong></p><p>這不是誇張，這是數學事實。讓我們來證明它。</p><h2 id="沒有激活函數會怎樣" tabindex="-1">沒有激活函數會怎樣？ <a class="header-anchor" href="#沒有激活函數會怎樣" aria-label="Permalink to &quot;沒有激活函數會怎樣？&quot;">​</a></h2><p>假設我們有一個三層的神經網路，每層都只做線性運算（沒有激活函數）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸入 x</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第一層：y₁ = W₁ × x + b₁</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第二層：y₂ = W₂ × y₁ + b₂</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第三層：y₃ = W₃ × y₂ + b₃</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>輸出 y₃</span></span></code></pre></div><p>現在讓我們把它展開：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y₃ = W₃ × y₂ + b₃</span></span>
<span class="line"><span>   = W₃ × (W₂ × y₁ + b₂) + b₃</span></span>
<span class="line"><span>   = W₃ × (W₂ × (W₁ × x + b₁) + b₂) + b₃</span></span>
<span class="line"><span>   = W₃ × W₂ × W₁ × x + W₃ × W₂ × b₁ + W₃ × b₂ + b₃</span></span>
<span class="line"><span>   = (W₃ × W₂ × W₁) × x + (W₃ × W₂ × b₁ + W₃ × b₂ + b₃)</span></span>
<span class="line"><span>   = W&#39; × x + b&#39;</span></span></code></pre></div><p>看到了嗎？三層網路最終變成了 <code>W&#39; × x + b&#39;</code>——這就是一個單層線性網路！</p><p><strong>三層等於一層。一百層也等於一層。</strong></p><p>這就像你把三片透明玻璃疊在一起，光線穿過去還是直線。不管疊多少片，都無法讓光線彎曲。</p><h2 id="激活函數的作用-引入非線性" tabindex="-1">激活函數的作用：引入非線性 <a class="header-anchor" href="#激活函數的作用-引入非線性" aria-label="Permalink to &quot;激活函數的作用：引入非線性&quot;">​</a></h2><p>激活函數在每層運算後加入「非線性轉換」：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸入 x</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第一層：y₁ = 激活函數(W₁ × x + b₁)   ← 彎曲！</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第二層：y₂ = 激活函數(W₂ × y₁ + b₂)  ← 再彎曲！</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第三層：y₃ = W₃ × y₂ + b₃</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>輸出 y₃</span></span></code></pre></div><p>這時候，數學展開就不能簡化了——因為激活函數「打斷」了線性組合。</p><p><strong>每一層的非線性轉換，讓網路能學習越來越複雜的模式。</strong></p><h2 id="直觀理解-xor-問題" tabindex="-1">直觀理解：XOR 問題 <a class="header-anchor" href="#直觀理解-xor-問題" aria-label="Permalink to &quot;直觀理解：XOR 問題&quot;">​</a></h2><p>讓我們用一個經典例子來說明為什麼需要非線性。這個例子在深度學習歷史上非常重要——它曾經讓整個 AI 領域停滯了十年。</p><h3 id="什麼是-xor" tabindex="-1">什麼是 XOR？ <a class="header-anchor" href="#什麼是-xor" aria-label="Permalink to &quot;什麼是 XOR？&quot;">​</a></h3><p><strong>XOR（Exclusive OR，互斥或）</strong> 是一種邏輯運算，中文叫「異或」。</p><p>它的規則很簡單：<strong>兩個輸入「不同」時輸出 1，「相同」時輸出 0。</strong></p><p>用白話說：</p><ul><li>「你和我<strong>不一樣</strong>」→ True（1）</li><li>「你和我<strong>一樣</strong>」→ False（0）</li></ul><h3 id="xor-的真值表" tabindex="-1">XOR 的真值表 <a class="header-anchor" href="#xor-的真值表" aria-label="Permalink to &quot;XOR 的真值表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">x₁</th><th style="text-align:center;">x₂</th><th style="text-align:center;">XOR 結果</th><th>解釋</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td>兩個都是 0，相同 → 輸出 0</td></tr><tr><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td style="text-align:center;">1</td><td>一個 0 一個 1，不同 → 輸出 1</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td>一個 1 一個 0，不同 → 輸出 1</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td>兩個都是 1，相同 → 輸出 0</td></tr></tbody></table><h3 id="與-and、or-的比較" tabindex="-1">與 AND、OR 的比較 <a class="header-anchor" href="#與-and、or-的比較" aria-label="Permalink to &quot;與 AND、OR 的比較&quot;">​</a></h3><p>讓我們比較三種邏輯運算：</p><table tabindex="0"><thead><tr><th style="text-align:center;">x₁</th><th style="text-align:center;">x₂</th><th style="text-align:center;">AND（且）</th><th style="text-align:center;">OR（或）</th><th style="text-align:center;">XOR（異或）</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">1</td><td style="text-align:center;">1</td><td style="text-align:center;">1</td><td style="text-align:center;">0</td></tr></tbody></table><ul><li><strong>AND</strong>：兩個都是 1 才輸出 1（「我<strong>和</strong>你都要同意」）</li><li><strong>OR</strong>：只要有一個是 1 就輸出 1（「我<strong>或</strong>你同意就行」）</li><li><strong>XOR</strong>：恰好一個是 1 才輸出 1（「只能有一個人同意」）</li></ul><h3 id="生活中的-xor-例子" tabindex="-1">生活中的 XOR 例子 <a class="header-anchor" href="#生活中的-xor-例子" aria-label="Permalink to &quot;生活中的 XOR 例子&quot;">​</a></h3><p><strong>1. 電燈開關（雙切開關）</strong></p><p>你家樓梯可能有兩個開關控制同一盞燈：</p><ul><li>兩個開關都朝上 → 燈滅</li><li>兩個開關都朝下 → 燈滅</li><li>一上一下 → 燈亮</li></ul><p>這就是 XOR！</p><p><strong>2. 選擇題：「以下哪個是對的？」</strong></p><p>如果答案是「A 或 B，但不能兩個都選」，這就是 XOR 邏輯。</p><p><strong>3. 密碼學中的加密</strong></p><p>XOR 在加密中很常用，因為它有一個神奇的性質：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A XOR B XOR B = A</span></span></code></pre></div><p>加密：明文 XOR 密鑰 = 密文<br> 解密：密文 XOR 密鑰 = 明文</p><h3 id="為什麼-xor-對神經網路很重要" tabindex="-1">為什麼 XOR 對神經網路很重要？ <a class="header-anchor" href="#為什麼-xor-對神經網路很重要" aria-label="Permalink to &quot;為什麼 XOR 對神經網路很重要？&quot;">​</a></h3><p>現在，讓我們把 XOR 的四個情況畫在二維平面上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    x₂</span></span>
<span class="line"><span>    ↑</span></span>
<span class="line"><span>  1 ┤  ●(0,1)=1      ○(1,1)=0</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>  0 ┤  ○(0,0)=0      ●(1,0)=1</span></span>
<span class="line"><span>    └──────────────────────→ x₁</span></span>
<span class="line"><span>       0             1</span></span></code></pre></div><ul><li>● 代表輸出 1（不同）</li><li>○ 代表輸出 0（相同）</li></ul><p><strong>問題來了：你能用一條直線把 ● 和 ○ 分開嗎？</strong></p><p>試試看：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>嘗試 1：水平線          嘗試 2：垂直線          嘗試 3：斜線</span></span>
<span class="line"><span>    ●     ○                 ●  │  ○                 ●     ○</span></span>
<span class="line"><span>   ─────────                   │                      ╲</span></span>
<span class="line"><span>    ○     ●                 ○  │  ●                 ○   ╲ ●</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>❌ 上面有 ●○            ❌ 左邊有 ●○            ❌ 還是分不開</span></span>
<span class="line"><span>   下面有 ○●               右邊有 ○●</span></span></code></pre></div><p><strong>無論你怎麼畫，一條直線都無法把 ● 和 ○ 分開！</strong></p><p>這就是「線性不可分」——單個神經元（本質上是畫一條直線）無法解決 XOR 問題。</p><h3 id="歷史插曲-ai-的第一次寒冬" tabindex="-1">歷史插曲：AI 的第一次寒冬 <a class="header-anchor" href="#歷史插曲-ai-的第一次寒冬" aria-label="Permalink to &quot;歷史插曲：AI 的第一次寒冬&quot;">​</a></h3><p>1969 年，Marvin Minsky 和 Seymour Papert 在《Perceptrons》一書中證明了單層感知器無法解決 XOR 問題。</p><p>這個發現導致了 AI 研究經費大幅縮減，開啟了所謂的「AI 寒冬」。</p><p>直到 1980 年代，人們發現<strong>多層網路 + 非線性激活函數</strong>可以解決 XOR，AI 研究才復甦。</p><h3 id="多層網路如何解決-xor" tabindex="-1">多層網路如何解決 XOR？ <a class="header-anchor" href="#多層網路如何解決-xor" aria-label="Permalink to &quot;多層網路如何解決 XOR？&quot;">​</a></h3><p>關鍵是：<strong>用兩條直線組合出一個區域</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一層神經元畫兩條線：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    線 A              線 B              組合起來</span></span>
<span class="line"><span>    ●     ○          ●     ○           ●  ╲  ○</span></span>
<span class="line"><span>      ╲                    ╱               ╲╱</span></span>
<span class="line"><span>    ○   ╲ ●          ○ ╱   ●           ○ ╱╲ ●</span></span>
<span class="line"><span>                                         ╱  ╲</span></span>
<span class="line"><span>                                       只有中間</span></span>
<span class="line"><span>                                       區域是「不同」</span></span></code></pre></div><ul><li><strong>神經元 A</strong>：判斷「x₁ + x₂ &gt; 0.5」（排除左下角）</li><li><strong>神經元 B</strong>：判斷「x₁ + x₂ &lt; 1.5」（排除右上角）</li><li><strong>輸出神經元</strong>：A AND B = 中間區域 = XOR 的答案</li></ul><p>這就是為什麼我們需要：</p><ol><li><strong>多層網路</strong>：組合多個簡單邊界</li><li><strong>非線性激活函數</strong>：讓每層的組合不會「塌縮」回單層</li></ol><h2 id="先搞懂幾個名詞" tabindex="-1">先搞懂幾個名詞 <a class="header-anchor" href="#先搞懂幾個名詞" aria-label="Permalink to &quot;先搞懂幾個名詞&quot;">​</a></h2><p>在介紹各種激活函數之前，先解釋幾個你會一直看到的術語。</p><h3 id="神經網路的結構" tabindex="-1">神經網路的結構 <a class="header-anchor" href="#神經網路的結構" aria-label="Permalink to &quot;神經網路的結構&quot;">​</a></h3><p>一個神經網路通常長這樣：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸入層        隱藏層         輸出層</span></span>
<span class="line"><span>(你的資料)   (中間處理)     (最終答案)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ○            ○              </span></span>
<span class="line"><span>  ○ ──────→   ○ ○ ──────→    ○</span></span>
<span class="line"><span>  ○            ○</span></span></code></pre></div><p><strong>輸入層</strong>：接收原始資料（例如：圖片的像素、房屋的坪數）</p><p><strong>隱藏層</strong>：中間的「思考」層，可以有很多層。叫「隱藏」是因為我們看不到它在想什麼，只看得到輸入和輸出。</p><p><strong>輸出層</strong>：給出最終答案</p><hr><h3 id="神經網路最常做的三種任務" tabindex="-1">神經網路最常做的三種任務 <a class="header-anchor" href="#神經網路最常做的三種任務" aria-label="Permalink to &quot;神經網路最常做的三種任務&quot;">​</a></h3><h4 id="_1-二分類-binary-classification" tabindex="-1">1. 二分類（Binary Classification） <a class="header-anchor" href="#_1-二分類-binary-classification" aria-label="Permalink to &quot;1. 二分類（Binary Classification）&quot;">​</a></h4><p><strong>問題</strong>：是 A 還是 B？只有兩個選項。</p><p><strong>例子</strong>：</p><ul><li>這封信是不是垃圾郵件？（是 / 否）</li><li>這張圖是不是貓？（是 / 否）</li><li>這筆交易是不是詐騙？（是 / 否）</li></ul><p><strong>輸出</strong>：一個數字，介於 0~1 之間，代表「是」的機率</p><ul><li>0.9 → 90% 機率是垃圾郵件</li><li>0.2 → 20% 機率是垃圾郵件（80% 機率不是）</li></ul><p><strong>輸出層用 Sigmoid</strong>（把任何數字壓到 0~1）</p><hr><h4 id="_2-多分類-multi-class-classification" tabindex="-1">2. 多分類（Multi-class Classification） <a class="header-anchor" href="#_2-多分類-multi-class-classification" aria-label="Permalink to &quot;2. 多分類（Multi-class Classification）&quot;">​</a></h4><p><strong>問題</strong>：是 A、B、C 還是 D？有多個選項，只能選一個。</p><p><strong>例子</strong>：</p><ul><li>這張圖是貓、狗、還是鳥？（三選一）</li><li>這個手寫數字是 0~9 哪一個？（十選一）</li><li>這篇文章是政治、體育、娛樂還是科技？（四選一）</li></ul><p><strong>輸出</strong>：多個數字，加起來等於 1，代表每個選項的機率</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>貓：0.7（70%）</span></span>
<span class="line"><span>狗：0.2（20%）</span></span>
<span class="line"><span>鳥：0.1（10%）</span></span>
<span class="line"><span>─────────</span></span>
<span class="line"><span>總和：1.0</span></span></code></pre></div><p><strong>輸出層用 Softmax</strong>（讓多個輸出加起來等於 1）</p><hr><h4 id="_3-迴歸-regression" tabindex="-1">3. 迴歸（Regression） <a class="header-anchor" href="#_3-迴歸-regression" aria-label="Permalink to &quot;3. 迴歸（Regression）&quot;">​</a></h4><p><strong>問題</strong>：預測一個「連續的數值」，不是選選項。</p><p><strong>例子</strong>：</p><ul><li>這間房子值多少錢？（500 萬、823 萬、任何數字都可能）</li><li>明天的氣溫是幾度？（18.5 度、32.7 度）</li><li>這個顧客會花多少錢？</li></ul><p><strong>輸出</strong>：一個數字，沒有範圍限制</p><p><strong>輸出層不加激活函數</strong>（直接輸出原始數值）</p><hr><h3 id="rnn-lstm-是什麼" tabindex="-1">RNN / LSTM 是什麼？ <a class="header-anchor" href="#rnn-lstm-是什麼" aria-label="Permalink to &quot;RNN / LSTM 是什麼？&quot;">​</a></h3><p><strong>RNN（Recurrent Neural Network，循環神經網路）</strong> 是專門處理「有順序」資料的網路。</p><p><strong>什麼是有順序的資料？</strong></p><ul><li>文字：「我 愛 台 灣」（字的順序很重要）</li><li>語音：聲音訊號隨時間變化</li><li>股價：每天的價格，有先後順序</li></ul><p>普通神經網路一次看完所有輸入，但 <strong>RNN 會一步一步處理</strong>，而且會「記住」前面看過的東西：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通神經網路：</span></span>
<span class="line"><span>[我, 愛, 台, 灣] ──→ 一次處理 ──→ 輸出</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RNN：</span></span>
<span class="line"><span>「我」──→ 處理 ──→ 記住</span></span>
<span class="line"><span>                      ↓</span></span>
<span class="line"><span>「愛」──→ 處理 ──→ 記住更多</span></span>
<span class="line"><span>                      ↓</span></span>
<span class="line"><span>「台」──→ 處理 ──→ 繼續累積</span></span>
<span class="line"><span>                      ↓</span></span>
<span class="line"><span>「灣」──→ 處理 ──→ 輸出</span></span></code></pre></div><p><strong>LSTM（Long Short-Term Memory）</strong> 是 RNN 的改良版，能「記更久」。</p><p><strong>這和激活函數有什麼關係？</strong> RNN/LSTM 內部需要用 Tanh，這是它的設計需求。你現在只要知道「RNN/LSTM 會用到 Tanh」就好。</p><hr><h3 id="快速對照表" tabindex="-1">快速對照表 <a class="header-anchor" href="#快速對照表" aria-label="Permalink to &quot;快速對照表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>術語</th><th>白話解釋</th></tr></thead><tbody><tr><td>隱藏層</td><td>中間的「思考」層，不是輸入也不是輸出</td></tr><tr><td>輸出層</td><td>最後給答案的那一層</td></tr><tr><td>二分類</td><td>是或不是？（兩個選項）</td></tr><tr><td>多分類</td><td>是 A/B/C 哪一個？（多個選項）</td></tr><tr><td>迴歸</td><td>數值是多少？（預測數字）</td></tr><tr><td>RNN/LSTM</td><td>處理「有順序」資料的特殊網路</td></tr></tbody></table><hr><h2 id="常見激活函數介紹" tabindex="-1">常見激活函數介紹 <a class="header-anchor" href="#常見激活函數介紹" aria-label="Permalink to &quot;常見激活函數介紹&quot;">​</a></h2><p>先別被數學公式嚇到！我們用「人」來比喻每種激活函數的個性。</p><h3 id="_1-relu-「正面積極-負面躺平」" tabindex="-1">1. ReLU：「正面積極，負面躺平」 <a class="header-anchor" href="#_1-relu-「正面積極-負面躺平」" aria-label="Permalink to &quot;1. ReLU：「正面積極，負面躺平」&quot;">​</a></h3><p><strong>個性</strong>：只對正面訊息有反應，負面訊息一律當作沒聽到。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸入 → ReLU → 輸出</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  5  →  5   （正的，原樣輸出）</span></span>
<span class="line"><span>  3  →  3   （正的，原樣輸出）</span></span>
<span class="line"><span> -2  →  0   （負的，當作零）</span></span>
<span class="line"><span>-10  →  0   （負的，當作零）</span></span></code></pre></div><p><strong>白話公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果輸入 &gt; 0：輸出 = 輸入</span></span>
<span class="line"><span>如果輸入 ≤ 0：輸出 = 0</span></span></code></pre></div><p><strong>圖形長這樣</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸出</span></span>
<span class="line"><span>  ↑</span></span>
<span class="line"><span>  │      ╱</span></span>
<span class="line"><span>  │    ╱</span></span>
<span class="line"><span>  │  ╱</span></span>
<span class="line"><span>──┼───────→ 輸入</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │（負的部分都貼在 0）</span></span></code></pre></div><p><strong>為什麼好用</strong>：</p><ul><li>✅ 超級簡單，計算超快</li><li>✅ 正的區域梯度是 1，不會消失</li><li>❌ 問題：如果某個神經元的輸入一直是負的，它就「死」了（永遠輸出 0，永遠學不動）</li></ul><p><strong>什麼時候用</strong>：隱藏層的首選，90% 的情況都先試它</p><hr><h3 id="_2-sigmoid-「什麼都壓縮到-0-1-之間」" tabindex="-1">2. Sigmoid：「什麼都壓縮到 0~1 之間」 <a class="header-anchor" href="#_2-sigmoid-「什麼都壓縮到-0-1-之間」" aria-label="Permalink to &quot;2. Sigmoid：「什麼都壓縮到 0~1 之間」&quot;">​</a></h3><p><strong>個性</strong>：不管你給我多大或多小的數字，我都幫你轉換成 0 到 1 之間的「信心程度」。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸入 → Sigmoid → 輸出</span></span>
<span class="line"><span></span></span>
<span class="line"><span> -10  →  0.00005  （非常負 → 接近 0）</span></span>
<span class="line"><span>  -2  →  0.12     （有點負 → 偏向 0）</span></span>
<span class="line"><span>   0  →  0.50     （剛好中間）</span></span>
<span class="line"><span>   2  →  0.88     （有點正 → 偏向 1）</span></span>
<span class="line"><span>  10  →  0.99995  （非常正 → 接近 1）</span></span></code></pre></div><p><strong>圖形長這樣</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸出</span></span>
<span class="line"><span>1 ┤         ────────</span></span>
<span class="line"><span>  │       ╱</span></span>
<span class="line"><span>  │     ╱</span></span>
<span class="line"><span>0.5┤────╱</span></span>
<span class="line"><span>  │   ╱</span></span>
<span class="line"><span>  │ ╱</span></span>
<span class="line"><span>0 ┤────────</span></span>
<span class="line"><span>  └─────────────→ 輸入</span></span>
<span class="line"><span>    -∞    0    +∞</span></span></code></pre></div><p>像一個 S 形，把任何數字「壓扁」到 0~1 之間。</p><p><strong>為什麼好用</strong>：</p><ul><li>✅ 輸出可以解讀成「機率」或「信心程度」</li><li>✅ 平滑的曲線，到處都能算導數</li><li>❌ 問題：當輸入太大或太小時，曲線幾乎是平的（梯度接近 0），學習會變很慢</li></ul><p><strong>什麼時候用</strong>：二分類問題的最後一層（輸出「是這個類別的機率」）</p><hr><h3 id="_3-tanh-「壓縮到-1-1-之間」" tabindex="-1">3. Tanh：「壓縮到 -1~1 之間」 <a class="header-anchor" href="#_3-tanh-「壓縮到-1-1-之間」" aria-label="Permalink to &quot;3. Tanh：「壓縮到 -1~1 之間」&quot;">​</a></h3><p><strong>個性</strong>：和 Sigmoid 很像，但輸出範圍是 -1 到 1，中心點在 0。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸入 → Tanh → 輸出</span></span>
<span class="line"><span></span></span>
<span class="line"><span> -10  →  -1.0     （非常負 → 接近 -1）</span></span>
<span class="line"><span>  -2  →  -0.96    （有點負 → 偏向 -1）</span></span>
<span class="line"><span>   0  →   0       （剛好中間）</span></span>
<span class="line"><span>   2  →   0.96    （有點正 → 偏向 +1）</span></span>
<span class="line"><span>  10  →   1.0     （非常正 → 接近 +1）</span></span></code></pre></div><p><strong>圖形長這樣</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸出</span></span>
<span class="line"><span>+1 ┤         ────────</span></span>
<span class="line"><span>   │       ╱</span></span>
<span class="line"><span> 0 ┤──────╱──────────</span></span>
<span class="line"><span>   │    ╱</span></span>
<span class="line"><span>-1 ┤────</span></span>
<span class="line"><span>   └─────────────→ 輸入</span></span>
<span class="line"><span>     -∞    0    +∞</span></span></code></pre></div><p><strong>和 Sigmoid 的差別</strong>：</p><ul><li>Sigmoid：0 到 1（全部是正的）</li><li>Tanh：-1 到 1（有正有負，中心在 0）</li></ul><p><strong>為什麼好用</strong>：</p><ul><li>✅ 輸出以 0 為中心，對下一層比較友善</li><li>✅ 梯度比 Sigmoid 大一點</li><li>❌ 問題：極端值時還是會有梯度消失</li></ul><p><strong>什麼時候用</strong>：RNN、LSTM 等序列模型</p><hr><h3 id="_4-leaky-relu-「負面也給一點反應」" tabindex="-1">4. Leaky ReLU：「負面也給一點反應」 <a class="header-anchor" href="#_4-leaky-relu-「負面也給一點反應」" aria-label="Permalink to &quot;4. Leaky ReLU：「負面也給一點反應」&quot;">​</a></h3><p><strong>個性</strong>：對正面訊息全力反應，對負面訊息給一點點小反應（不完全躺平）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸入 → Leaky ReLU → 輸出</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  5  →  5      （正的，原樣輸出）</span></span>
<span class="line"><span>  3  →  3      （正的，原樣輸出）</span></span>
<span class="line"><span> -2  → -0.02   （負的，乘上 0.01）</span></span>
<span class="line"><span>-10  → -0.1    （負的，乘上 0.01）</span></span></code></pre></div><p><strong>白話公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果輸入 &gt; 0：輸出 = 輸入</span></span>
<span class="line"><span>如果輸入 ≤ 0：輸出 = 0.01 × 輸入（給 1% 的反應）</span></span></code></pre></div><p><strong>圖形長這樣</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸出</span></span>
<span class="line"><span>  ↑</span></span>
<span class="line"><span>  │      ╱</span></span>
<span class="line"><span>  │    ╱</span></span>
<span class="line"><span>  │  ╱</span></span>
<span class="line"><span>──┼───────→ 輸入</span></span>
<span class="line"><span> ╱│</span></span>
<span class="line"><span>（負的部分有一點點斜率）</span></span></code></pre></div><p><strong>為什麼好用</strong>：</p><ul><li>✅ 解決 ReLU 的「神經元死亡」問題</li><li>✅ 計算還是很快</li></ul><p><strong>什麼時候用</strong>：當你用 ReLU 發現很多神經元都「死」了，就換這個試試</p><hr><h3 id="總結比較" tabindex="-1">總結比較 <a class="header-anchor" href="#總結比較" aria-label="Permalink to &quot;總結比較&quot;">​</a></h3><table tabindex="0"><thead><tr><th>激活函數</th><th>一句話形容</th><th style="text-align:center;">輸出範圍</th><th>最適合用在</th></tr></thead><tbody><tr><td>ReLU</td><td>正面積極，負面歸零</td><td style="text-align:center;">[0, +∞)</td><td>隱藏層（首選）</td></tr><tr><td>Sigmoid</td><td>壓成 0~1 的信心值</td><td style="text-align:center;">(0, 1)</td><td>二分類輸出層</td></tr><tr><td>Tanh</td><td>壓成 -1~1，中心在 0</td><td style="text-align:center;">(-1, 1)</td><td>RNN/LSTM</td></tr><tr><td>Leaky ReLU</td><td>負面也給 1% 反應</td><td style="text-align:center;">(-∞, +∞)</td><td>ReLU 不夠好時</td></tr></tbody></table><p><strong>記憶口訣</strong>：</p><ul><li>隱藏層 → 先試 <strong>ReLU</strong></li><li>二分類輸出 → 用 <strong>Sigmoid</strong></li><li>序列模型 → 用 <strong>Tanh</strong></li><li>ReLU 壞掉 → 換 <strong>Leaky ReLU</strong></li></ul><h2 id="激活函數的導數-為什麼重要" tabindex="-1">激活函數的導數：為什麼重要？ <a class="header-anchor" href="#激活函數的導數-為什麼重要" aria-label="Permalink to &quot;激活函數的導數：為什麼重要？&quot;">​</a></h2><p>在訓練神經網路時，我們需要計算每個激活函數的「導數」（梯度），因為反向傳播需要用到。</p><table tabindex="0"><thead><tr><th>激活函數</th><th>導數</th></tr></thead><tbody><tr><td>ReLU</td><td>1 if x &gt; 0 else 0</td></tr><tr><td>Sigmoid</td><td>σ(x) × (1 - σ(x))</td></tr><tr><td>Tanh</td><td>1 - tanh²(x)</td></tr></tbody></table><p><strong>梯度消失問題</strong>：</p><p>Sigmoid 的導數最大值只有 0.25（在 x=0 處）。這意味著每經過一層，梯度最多保留原來的 1/4。</p><p>如果有 10 層網路，梯度會變成原來的 (1/4)^10 ≈ 0.000001。</p><p>梯度太小，網路就學不動了——這就是「梯度消失」。</p><p>ReLU 的導數是 0 或 1，所以不會有這個問題（但會有 Dead ReLU 問題）。</p><h2 id="互動視覺化" tabindex="-1">互動視覺化 <a class="header-anchor" href="#互動視覺化" aria-label="Permalink to &quot;互動視覺化&quot;">​</a></h2><p>我製作了一個互動工具，讓你可以：</p><ul><li>比較不同激活函數的形狀</li><li>觀察導數（梯度）的變化</li><li>調整輸入值，看輸出如何變化</li></ul><p>👉 <a href="/htmls/activation-functions.html" target="_blank">激活函數互動視覺化</a></p><p>建議你實際操作，感受：</p><ol><li>ReLU 在 x &lt; 0 時梯度為 0（Dead ReLU）</li><li>Sigmoid 在極端值時梯度接近 0（梯度消失）</li><li>不同激活函數的輸出範圍差異</li></ol><h2 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to &quot;小結&quot;">​</a></h2><p>今天我們學到了：</p><ol><li><strong>沒有激活函數，多層網路等於單層</strong>——這是數學事實</li><li><strong>激活函數引入非線性</strong>，讓網路能學習複雜模式</li><li><strong>XOR 問題</strong>展示了為什麼線性模型有局限</li><li><strong>常見激活函數</strong>：ReLU（隱藏層首選）、Sigmoid（二分類輸出）、Tanh（RNN）</li><li><strong>梯度消失問題</strong>：Sigmoid/Tanh 的導數太小，ReLU 緩解了這個問題</li><li><strong>選擇原則</strong>：隱藏層用 ReLU，輸出層根據任務選擇</li></ol><h2 id="下一篇預告" tabindex="-1">下一篇預告 <a class="header-anchor" href="#下一篇預告" aria-label="Permalink to &quot;下一篇預告&quot;">​</a></h2><p>現在我們知道神經元如何運算、為什麼需要激活函數。但還有一個關鍵問題：</p><p><strong>神經網路的權重是怎麼學出來的？</strong></p><p>下一篇我們會介紹<strong>梯度下降</strong>——神經網路學習的核心算法。我們會用 3D 視覺化來展示，什麼是「順著斜坡往下走，找到谷底」。</p><hr><p><em>本文是「從零理解神經網路」系列的第二篇。如果你覺得有幫助，歡迎分享給也在學習 ML 的朋友。</em></p>`,178)])])}const u=s(p,[["render",l]]);export{h as __pageData,u as default};
